import subprocess, sys, struct

EXE="/workspace/executable"
FA="/tmp/rng/n64.fa"
N=64

def fmt(x):
    return "%.17g" % x

cache={}
def kept(frac, seed):
    key=(frac,seed)
    if key in cache: return cache[key]
    out=subprocess.run([EXE,"seq","-s%d"%seed,"-f",fmt(frac),FA],capture_output=True,text=True).stdout
    s=set()
    for line in out.split("\n"):
        if line.startswith(">r"): s.add(int(line[2:]))
    cache[key]=s
    return s

def recover(seed, nidx=41):
    # per index interval [lo,hi): kept iff r_i < frac  => r_i in [lo, hi]
    lo=[0.0]*nidx; hi=[1.0]*nidx
    def apply(frac, ks):
        for i in range(nidx):
            if i in ks:
                # r_i < frac  (hypothesis)  => hi = min(hi, frac)
                if frac<hi[i]: hi[i]=frac
            else:
                if frac>lo[i]: lo[i]=frac
    for it in range(4000):
        # find widest interval
        widths=[(hi[i]-lo[i], i) for i in range(nidx)]
        widths.sort(reverse=True)
        w,i=widths[0]
        mid=lo[i]+(hi[i]-lo[i])/2
        if mid<=lo[i] or mid>=hi[i]: break
        apply(mid, kept(mid,seed))
    return lo,hi

if __name__=="__main__":
    seeds=[0,1,11,42,12345,2**31]
    res={}
    for s in seeds:
        lo,hi=recover(s)
        res[s]=(lo,hi)
        print("seed",s)
        for i in range(41):
            print("  %2d  %.17g  %.17g  %s"%(i,lo[i],hi[i], "EXACT" if lo[i]==hi[i] or hi[i]-lo[i]<1e-16 else ""))
    import json
    json.dump({str(k):[v[0],v[1]] for k,v in res.items()}, open("/tmp/rng/recovered.json","w"))
EOF
